import { test, expect } from '@playwright/test';
import {
  blockWrites, LOAD, CONVERSATION_TITLE, CONVERSATION_URL, lastMessageTime, messageInput, personalAreaHeading,
} from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

test.describe('Чат / переписки — открытие переписки', () => {
  test('Десктоп: меню «אזור אישי» остаётся рядом с открытой перепиской #bb6e6d @desktop @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto(CONVERSATION_URL);
    const input = messageInput(page);
    await expect(input).toBeVisible(LOAD);

    const menu = personalAreaHeading(page);
    await expect(menu, 'меню «אזור אישי» в первом экране').toBeInViewport(LOAD);
    await expect(page.getByRole('heading', { name: 'הודעות ושיחות' })).toBeInViewport();
    await expect(page.getByRole('heading', { name: CONVERSATION_TITLE }).first()).toBeInViewport();
    await expect(lastMessageTime(page)).toBeInViewport();
    await expect(page.getByRole('button', { name: 'חזרה לשיחות' })).toBeHidden();

    // RTL: меню справа от переписки, на одном уровне по вертикали
    const menuBox = (await menu.boundingBox())!;
    const inputBox = (await input.boundingBox())!;
    expect(menuBox.x, 'меню справа от поля ввода').toBeGreaterThanOrEqual(inputBox.x + inputBox.width);
    expect(menuBox.y, 'меню начинается выше нижней границы переписки').toBeLessThan(inputBox.y);
  });
});
